<script setup>
import { computed, reactive, ref } from 'vue'
import { planningLoadProfile, configurationTotals, downloadPlanningCsv } from '../utils/plannerPss.js'
const props = defineProps({ stations: { type: Array, default: () => [] }, beforeStations: { type: Array, default: () => [] }, additions: { type: Number, default: 0 } })
const hour = ref(19)
const settings = reactive({ commercialShare:45, officeShare:25, residentialShare:30, utilization:.65, transformerKva:null, baseLoadKw:0,
  powerFactor:.9, warningRate:.8, solarKw:0, batteryKwh:200, batteryKw:50, efficiency:.9 })
const fields = [{key:'transformerKva',label:'评估范围配变容量 kVA',step:1},{key:'baseLoadKw',label:'基础用电负荷 kW',step:1},{key:'powerFactor',label:'功率因数（0～1）',step:.01,max:1},{key:'warningRate',label:'负载警戒比例（0～1）',step:.01,max:1},{key:'utilization',label:'充电并发系数（0～1）',step:.01,max:1},{key:'solarKw',label:'光伏装机 kW',step:1},{key:'batteryKwh',label:'储能容量 kWh',step:10},{key:'batteryKw',label:'储能充放电功率 kW',step:5},{key:'efficiency',label:'储能往返效率（0～1）',step:.01,max:1}]
const sectors = [{key:'commercialShare',label:'商业 / 枢纽',color:'#f59e0b'},{key:'officeShare',label:'办公 / 医教',color:'#4389ed'},{key:'residentialShare',label:'居民社区',color:'#9571df'}]
const profile = computed(() => planningLoadProfile(props.stations, settings)), baseline = computed(() => planningLoadProfile(props.beforeStations, settings))
const totals = computed(() => configurationTotals(props.stations)), current = computed(() => profile.value?.hours[hour.value])
const chartMax = computed(() => Math.max(1, ...(profile.value?.hours.flatMap(row => [row.beforeKw,row.afterKw]) || []), profile.value?.transformerKw ? profile.value.transformerKw * settings.warningRate : 0))
const path = field => profile.value?.hours.map(row => `${40+row.hour/23*650},${260-row[field]/chartMax.value*220}`).join(' ')
const fmt = (value,digits=0) => value == null ? '待补充' : value.toFixed(digits)
function exportProfile() { downloadPlanningCsv('魏都区-24小时车网情景.csv',['时刻','原始负荷kW','光伏kW','储能充电kW','储能放电kW','调节后负荷kW','储能电量kWh','负载率%'],profile.value.hours.map(row=>[row.hour,row.beforeKw,row.solarKw,row.batteryChargeKw,row.batteryDischargeKw,row.afterKw,row.storedKwh,row.loadRate])) }
</script>
<template>
  <section class="pss-workbench" aria-label="车网协同与配网承载力">
    <div class="pss-intro"><div><span class="pss-eyebrow">VEHICLE–GRID SCENARIOS</span><h2>让建站方案进入 24 小时负荷情景</h2><p>根据当前 {{ totals.stations }} 个站点的已知配置，比较充电负荷、光伏与储能调节。</p></div><button :disabled="!profile" @click="exportProfile">导出逐时数据</button></div>
    <p class="pss-alert">情景仿真：未接入电网遥测与实测时序。配变容量需覆盖本次评估的同一范围，不能将单台变压器与全区总负荷直接比较。</p>
    <div class="pss-kpis"><article><span>{{ hour }}:00 调节后总负荷</span><strong>{{ fmt(current?.afterKw) }}<small> kW</small></strong><p>含基础负荷、充电、光伏与储能</p></article><article><span>配变负载率</span><strong>{{ fmt(current?.loadRate,1) }}<small>{{ current?.loadRate == null ? '' : '%' }}</small></strong><p>{{ profile?.overloadHours == null ? '填写同范围配变容量后校核' : '越过警戒线 ' + profile.overloadHours + ' 小时' }}</p></article><article><span>全天峰值变化</span><strong>{{ fmt(profile?.peakReductionKw) }}<small> kW</small></strong><p>原峰值减调节后峰值，负值表示增峰</p></article><article><span>警戒线以上供能缺口</span><strong>{{ fmt(profile?.requiredStorageKwh) }}<small>{{ profile?.requiredStorageKwh == null ? '' : ' kWh' }}</small></strong><p>未计储能功率限制的能量参考</p></article></div>
    <div class="pss-columns"><div class="pss-main-column">
      <section class="pss-card"><div class="pss-card-heading"><h3>逐时负荷与光储调节</h3><label>{{ String(hour).padStart(2,'0') }}:00 <input v-model.number="hour" type="range" min="0" max="23" aria-label="电网评估时刻" /></label></div><template v-if="profile"><svg class="pss-load-chart" viewBox="0 0 720 300" role="img" aria-label="24小时原始与调节后负荷曲线"><path d="M40 30V260H690" fill="none" stroke="#cbd5e1"/><line v-for="tick in [0,.5,1]" :key="tick" x1="40" x2="690" :y1="260-tick*220" :y2="260-tick*220" stroke="#e8edf4"/><line v-if="profile.transformerKw" x1="40" x2="690" :y1="260-profile.transformerKw*settings.warningRate/chartMax*220" :y2="260-profile.transformerKw*settings.warningRate/chartMax*220" stroke="#dc5c65" stroke-dasharray="5 4"/><polyline :points="path('beforeKw')" fill="none" stroke="#7d90b1" stroke-width="2.5"/><polyline :points="path('afterKw')" fill="none" stroke="#2563eb" stroke-width="3"/><line :x1="40+hour/23*650" :x2="40+hour/23*650" y1="30" y2="260" stroke="#93b4f5" stroke-dasharray="3 4"/><text x="42" y="20">{{ Math.round(chartMax).toLocaleString() }} kW</text><text v-for="tick in [0,6,12,18,23]" :key="tick" :x="40+tick/23*650" y="283" text-anchor="middle">{{ tick }}:00</text></svg><div class="pss-curve-key"><span>灰：调节前</span><span class="pss-after-blue">蓝：光储调节后</span><span class="pss-before">虚线：负载警戒线</span></div><div class="pss-hour-bars"><button v-for="row in profile.hours" :key="row.hour" :class="{active:hour===row.hour}" :aria-label="row.hour + '点充电负荷'" :title="row.hour+'点充电 '+fmt(row.chargingKw)+' kW'" @click="hour=row.hour"><span class="pss-hour-stack"><i v-for="(value,index) in row.sectors" :key="index" :style="{height:Math.max(0,value/chartMax*100)+'%',background:sectors[index].color}"></i></span><small>{{ row.hour }}</small></button></div><div class="pss-curve-key"><span v-for="sector in sectors" :key="sector.key" :style="{color:sector.color}">{{ sector.label }}</span></div><p class="pss-note">参考文件的三类日内曲线作为情景形状，权重与并发系数可调。储能从空电量起算，11～15 时充电、18～21 时放电，逐时遵守功率、电量与效率约束；未假设车辆提供 V2G 回送。</p></template><p v-else class="pss-empty">配置能力未知或参数无效，暂不能绘制负荷。请补充配置，比例与效率需为有效值。</p></section>
      <section class="pss-card"><h3>方案与运行校核</h3><div class="pss-table-wrap"><table class="pss-table"><thead><tr><th>比较项</th><th>现有站点</th><th>当前草稿方案</th></tr></thead><tbody><tr><td>已知配置能力 kW</td><td>{{ fmt(baseline?.capacityKw) }}</td><td>{{ fmt(profile?.capacityKw) }}</td></tr><tr><td>调节前峰值 kW</td><td>{{ fmt(baseline?.beforePeak) }}</td><td>{{ fmt(profile?.beforePeak) }}</td></tr><tr><td>光储调节后峰值 kW</td><td>{{ fmt(baseline?.afterPeak) }}</td><td>{{ fmt(profile?.afterPeak) }}</td></tr></tbody></table></div><p class="pss-note">新增 {{ additions }} 站；草稿的新增、移除和参数调整即时进入负荷情景，无需等待空间分析。{{ totals.unknown ? totals.unknown + ' 个站点配置未知，仅计算已知部分。' : '' }}{{ totals.simulated ? '配置能力包含演示或模拟参数。' : '' }}</p><p v-if="profile?.overloadHours > 0" class="pss-alert">有 {{ profile.overloadHours }} 个小时超过设定警戒线。可调整站点规模、并发系数或光储参数后比较；接电方案需以电网核查为准。</p><p v-else-if="profile?.overloadHours === 0" class="pss-note">本情景未越过设定警戒线；尚未计入逐台区拓扑、线路和配电保护约束。</p></section>
    </div><aside class="pss-side-column"><section class="pss-card"><h3>配网与光储参数</h3><p class="pss-note">缺失的实测值留空，其余默认值是情景假设。</p><div class="pss-input-grid"><label v-for="field in fields" :key="field.key" class="pss-field">{{ field.label }}<input v-model.number="settings[field.key]" type="number" min="0" :max="field.max" :step="field.step" placeholder="待补充" :aria-label="field.label" /></label></div></section><section class="pss-card"><h3>三类负荷结构</h3><label v-for="sector in sectors" :key="sector.key" class="pss-field">{{ sector.label }}（相对权重）<input v-model.number="settings[sector.key]" type="range" min="0" max="100" step="5" :aria-label="sector.label+'负荷权重'" /><span>{{ settings[sector.key] }}</span></label><p class="pss-note">三类权重自动归一化，不代表已采集到对应类型的真实充电曲线。</p></section></aside></div>
  </section>
</template>
